<?php
require_once __DIR__.'/_bootstrap.php'; require_once __DIR__.'/_layout.php';
$session=sc_require_session();$error=null;try{$state=$sc_repository->call_state($session);}catch(Throwable $exception){$state=[];$error='Call handling is unavailable on this FusionPBX installation.';}
$rules=[['forward_all_enabled','forward_all_destination','Always forward','Send every call to this destination.'],['forward_busy_enabled','forward_busy_destination','When busy','Forward when your extension is busy.'],['forward_no_answer_enabled','forward_no_answer_destination','No answer','Forward calls you do not answer.'],['forward_user_not_registered_enabled','forward_user_not_registered_destination','Not registered','Forward when your device is offline.']];
sc_render_header($session,'calls','Call handling');
?>
<?php if($error){?><div class="sc-alert error"><?=sc_escape($error)?></div><?php }else{?><form method="post" action="action.php"><input type="hidden" name="csrf" value="<?=sc_escape($session['csrf'])?>"><input type="hidden" name="action" value="save_calls"><input type="hidden" name="expected_update_date" value="<?=sc_escape($state['update_date']??'')?>"><section class="sc-card"><h2>Availability</h2><label class="sc-check"><input type="checkbox" name="do_not_disturb" value="true" <?=sc_bool($state['do_not_disturb']??false)?'checked':''?>><span><b>Do not disturb</b><br><span class="sc-muted">Calls will not ring this extension.</span></span></label></section><div class="sc-divider"></div><div class="sc-grid"><?php foreach($rules as [$enabled,$destination,$label,$help]){?><section class="sc-card sc-forward"><label class="sc-check"><input type="checkbox" name="<?=sc_escape($enabled)?>" value="true" <?=sc_bool($state[$enabled]??false)?'checked':''?>><b><?=sc_escape($label)?></b></label><input class="sc-input" inputmode="tel" autocomplete="tel" name="<?=sc_escape($destination)?>" value="<?=sc_escape($state[$destination]??'')?>" placeholder="Extension or approved number"><span class="sc-muted"><?=sc_escape($help)?></span></section><?php }?></div><div class="sc-divider"></div><div class="sc-actions"><button class="sc-button" type="submit">Save call handling</button></div></form><?php }?>
<?php sc_render_footer(); ?>
